import path from"node:path";import{readProcessIdentity}from"@openclaw/proc-safe/identity";import{PinnedProcess,bindCurrentProcessLifetimeTo}from"@openclaw/proc-safe/windows-job";
//!src/process/supervisor/service-child-windows-task-launcher.ts
function bindWindowsTaskLauncher(e=`wscript`){const requireProcess=(e,t,n)=>{const r=PinnedProcess.open(e,{access:n});if(!r)throw new Error(`Windows task ${t} is no longer present`);return r};const requireLive=(e,t)=>{if(e.identity.exited)throw new Error(`Windows task ${t} is no longer live`)};const t=readProcessIdentity(process.pid);if(!t)throw new Error(`Windows task supervisor is no longer present`);let n;let r;try{n=requireProcess(t.parentPid,`CMD`,e===`cmd`?`lifetime-owner`:`observe`);const i=n.identity;if(path.win32.basename(n.imagePath).toLowerCase()!==`cmd.exe`||i.startTimeMicros>t.startTimeMicros)throw new Error(`Windows task supervisor lost its original CMD launcher`);if(e===`cmd`){requireLive(n,`CMD launcher`);bindCurrentProcessLifetimeTo(n);return}r=requireProcess(i.parentPid,`WScript`,`lifetime-owner`);const a=r.identity;if(path.win32.basename(r.imagePath).toLowerCase()!==`wscript.exe`||a.startTimeMicros>i.startTimeMicros)throw new Error(`Windows task supervisor lost its original WScript launcher`);requireLive(n,`CMD launcher`);requireLive(r,`WScript launcher`);bindCurrentProcessLifetimeTo(r)}finally{r?.close();n?.close()}}export{bindWindowsTaskLauncher};